### 💡 3. `script.js` (Lógica da Busca)

Este JavaScript captura o termo de busca e exibe uma mensagem de simulação na tela.

```javascript
// 1. Seleciona os elementos do DOM
const searchInput = document.getElementById('searchInput');
const searchButton = document.getElementById('searchButton');
const resultsArea = document.getElementById('resultsArea');

// Função que simula a busca de informações
function handleSearch() {
    // Captura o valor digitado pelo usuário
    const searchTerm = searchInput.value.trim();

    // Limpa resultados anteriores
    resultsArea.innerHTML = ''; 

    if (searchTerm === "") {
        // Se o campo estiver vazio
        resultsArea.innerHTML = '<p style="color: red;">Por favor, digite um termo de busca válido.</p>';
        return;
    }

    // --- SIMULAÇÃO DE BUSCA ---
    // Em um site real, neste ponto você usaria `fetch()` para enviar o 'searchTerm'
    // para um servidor/API.

    console.log(`Termo de busca enviado: ${searchTerm}`);

    // Exibe um resultado simulado para demonstrar o funcionamento
    const simulatedResult = `
        <h3>✅ Resultado Encontrado para: "${searchTerm}"</h3>
        <p>Este é um resultado simulado. Se este fosse um site real, o back-end (servidor) 
        receberia este termo e retornaria os dados corretos do banco de dados.</p>
        <ul>
            <li>Detalhe 1: Informação relacionada a ${searchTerm}.</li>
            <li>Detalhe 2: Mais dados sobre o tema.</li>
        </ul>
    `;

    // Exibe o resultado na área definida
    resultsArea.innerHTML = simulatedResult;
}

// 2. Adiciona o evento de clique ao botão
searchButton.addEventListener('click', handleSearch);

// 3. Adiciona um evento para buscar ao pressionar "Enter" no campo de input
searchInput.addEventListener('keypress', function(event) {
    // Verifica se a tecla pressionada é Enter (código 13)
    if (event.key === 'Enter') {
        handleSearch();
    }
});

console.log("A interface de busca está pronta!");
```

